// ===========================================================================
// CASAGENCIA · LIBRERIA COMUN DEL ASISTENTE TELEFONICO
// ---------------------------------------------------------------------------
// Este bloque se inyecta automaticamente al principio de los nodos Code de
// los workflows BuscarDisponibilidadCalendario, ConfirmarCitaCalendario y
// BuscarCitaPorTelefono.
//
// NO editar a mano dentro de n8n: editar este fichero y volver a desplegar
// con  python3 n8n/casagencia/build_workflows.py --deploy
// ===========================================================================

const ZONA = 'Europe/Madrid';

// --- Horario de oficina de cada asesora ------------------------------------
// La visita dura 1 hora y tiene que caber ENTERA dentro de un bloque.
const HORARIOS = {
  Carmen: { lv: [['09:30', '14:00'], ['16:00', '19:30']], sab: [['10:00', '14:00']], dom: null },
  Gisela: { lv: [['09:00', '14:00'], ['16:00', '19:00']], sab: null,                 dom: null }
};

// --- Festivos ---------------------------------------------------------------
// GUARDAFUEGOS: no depende de que la comercial bloquee nada en su calendario.
// TODOS  = festivos nacionales y de la Comunitat Valenciana (fecha fija).
// BN/OR/CS/VR = fiestas locales de cada zona. RELLENAR CADA ANO.
const FESTIVOS = {
  TODOS: [
    '2026-10-09', // Dia de la Comunitat Valenciana
    '2026-10-12', // Fiesta Nacional
    '2026-11-01', // Todos los Santos
    '2026-12-06', // Constitucion
    '2026-12-08', // Inmaculada
    '2026-12-25', // Navidad
    // Las 12 fiestas de la Comunitat Valenciana de 2027, aprobadas por la
    // Generalitat. OJO: las tres de marzo son MOVIBLES (dependen de la Pascua),
    // asi que cada ano hay que volver a mirarlas; no vale copiar las del ano
    // anterior. El 15 de agosto de 2027 cae en domingo y no esta en la lista
    // oficial, por eso no aparece aqui.
    '2027-01-01', '2027-01-06',
    '2027-03-19',  // San Jose
    '2027-03-26',  // Viernes Santo
    '2027-03-29',  // Lunes de Pascua
    '2027-05-01',
    '2027-10-09', '2027-10-12', '2027-11-01', '2027-12-06', '2027-12-08', '2027-12-25'
  ],
  BN: [], // Benicasim  -> fiestas locales: ANADIR
  OR: [], // Oropesa    -> fiestas locales: ANADIR
  CS: [], // Castellon  -> fiestas locales (Magdalena, etc.): ANADIR
  VR: []  // Vila-real  -> fiestas locales: ANADIR
};

// --- Routing de asesora (ARREGLO #7: mapeo explicito, sin fallback silencioso)
const ASESORA_POR_PREFIJO = { BN: 'Carmen', OR: 'Carmen', CS: 'Gisela', VR: 'Gisela' };
const CALENDARIO_POR_ASESORA = {
  Carmen: 'carmen@casagencia.com',
  Gisela: 'gisela@casagencia.com'
};
const CALENDARIO_POR_DEFECTO = 'gisela@casagencia.com'; // solo para que el nodo no reviente

// --- Titulos de eventos de dia completo que SI bloquean el dia (ARREGLO #8) --
const RE_DIA_BLOQUEANTE = /vacacion|vacanc|baja|festiv|cerrad|ausent|no disponible|libranza|asuntos propios/i;

// ---------------------------------------------------------------------------
// Telefonos (ARREGLO #12)
// ---------------------------------------------------------------------------
function normalizarTelefono(raw) {
  let s = String(raw ?? '').trim();
  const teniaMas = s.startsWith('+');
  s = s.replace(/\D/g, '');
  if (!teniaMas && s.startsWith('00')) s = s.slice(2);
  if (/^[6789]\d{8}$/.test(s)) s = '34' + s;          // movil/fijo espanol sin prefijo
  const nacional = s.startsWith('34') ? s.slice(2) : s;
  return {
    e164: s ? '+' + s : '',
    nacional,
    digitos: s,
    valido: s.length >= 8 && s.length <= 15,
    original: String(raw ?? '')
  };
}

// ---------------------------------------------------------------------------
// Referencias y asesora
// ---------------------------------------------------------------------------
function prefijoDeReferencia(ref) {
  const m = String(ref ?? '').toUpperCase().match(/[A-Z]{2}/);
  return m ? m[0] : '';
}

function resolverAsesora(ref) {
  const prefijo = prefijoDeReferencia(ref);
  const asesora = ASESORA_POR_PREFIJO[prefijo] || null;
  return {
    prefijo,
    asesora,
    conocida: !!asesora,
    calendario: asesora ? CALENDARIO_POR_ASESORA[asesora] : CALENDARIO_POR_DEFECTO
  };
}

// ---------------------------------------------------------------------------
// Alquiler: NO se agenda visita (peticion de Casagencia, sept. 2026)
// ---------------------------------------------------------------------------
// El mercado de alquiler esta muy tensionado y la mitad de los interesados no
// pasa la criba de la asesora. Si Sara agendase todas las visitas, el calendario
// se llenaria de citas que luego hay que deshacer. Asi que en alquiler Sara
// cualifica al cliente y pasa el aviso: la asesora llama y agenda ella.
//
// Las referencias de alquiler acaban en -A y las de venta en -V, pero hay algun
// caso suelto (un traspaso de local marcado como alquiler con referencia -V).
// Por eso basta con que CUALQUIERA de las dos senales diga alquiler.
function esPeticionAlquiler(referencia, tipoTransaccion) {
  const t = String(tipoTransaccion ?? '').toLowerCase();
  if (t.includes('alquiler') || t.includes('traspaso') || t.includes('rent')) return true;
  return /-A$/i.test(String(referencia ?? '').trim());
}

const MSG_ALQUILER_SIN_AGENDA =
  'En alquiler NO se agenda la visita desde aqui. Explicale al cliente con naturalidad que, ' +
  'por la cantidad de solicitudes que hay, es la asesora de la zona quien organiza las visitas ' +
  'de alquiler y le va a llamar para concretarla. Antes de despedirte, hazle las preguntas de ' +
  'cualificacion de alquiler y registra el aviso con registrarMensaje.';

// ---------------------------------------------------------------------------
// Horario / festivos
// ---------------------------------------------------------------------------
function esFestivo(fecha, prefijo) {
  const lista = [].concat(FESTIVOS.TODOS || [], FESTIVOS[prefijo] || []);
  return lista.includes(fecha);
}

function bloquesDelDia(fecha, asesora) {
  const h = HORARIOS[asesora] || HORARIOS.Gisela;
  const wd = DateTime.fromFormat(fecha, 'yyyy-MM-dd', { zone: ZONA }).weekday;
  if (wd === 7) return h.dom;
  if (wd === 6) return h.sab;
  return h.lv;
}

// Devuelve { valido, motivo } para una fecha+hora concretas.
// motivo: ok | formato | pasado | cerrado | festivo | fuera_horario
function validarFranja(fecha, hora, asesora, prefijo, ahora) {
  const ini = DateTime.fromFormat(`${fecha} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  if (!ini.isValid) return { valido: false, motivo: 'formato' };
  if (ini < ahora) return { valido: false, motivo: 'pasado' };
  if (esFestivo(fecha, prefijo)) return { valido: false, motivo: 'festivo' };

  const bloques = bloquesDelDia(fecha, asesora);
  if (!bloques || !bloques.length) return { valido: false, motivo: 'cerrado' };

  const fin = ini.plus({ hours: 1 });
  const cabe = bloques.some(([a, b]) => {
    const ba = DateTime.fromFormat(`${fecha} ${a}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    const bb = DateTime.fromFormat(`${fecha} ${b}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    return ini >= ba && fin <= bb;
  });
  return cabe ? { valido: true, motivo: 'ok' } : { valido: false, motivo: 'fuera_horario' };
}

// ---------------------------------------------------------------------------
// Ocupacion del calendario (ARREGLO #8)
// ---------------------------------------------------------------------------
// Un evento de dia completo (cumpleanos, recordatorio, calendario de festivos
// importado...) ya NO borra el dia entero. Solo bloquea si su titulo indica
// ausencia real. Tambien se respeta transparency='transparent' (marcado Libre).
function rangosOcupados(items) {
  const out = [];
  for (const it of items) {
    const j = (it && it.json) ? it.json : it;
    if (!j || !j.start) continue;
    if (j.status === 'cancelled') continue;
    if (j.transparency === 'transparent') continue;

    if (!j.start.dateTime) {
      if (!RE_DIA_BLOQUEANTE.test(String(j.summary || ''))) continue; // no bloquea
      const d0 = DateTime.fromISO(j.start.date, { zone: ZONA }).startOf('day');
      const d1 = j.end && j.end.date
        ? DateTime.fromISO(j.end.date, { zone: ZONA }).startOf('day')
        : d0.plus({ days: 1 });
      out.push({ start: d0, end: d1, titulo: j.summary || '', diaCompleto: true });
      continue;
    }

    const s = DateTime.fromISO(j.start.dateTime, { zone: ZONA });
    const e = j.end && j.end.dateTime
      ? DateTime.fromISO(j.end.dateTime, { zone: ZONA })
      : s.plus({ hours: 1 });
    out.push({ start: s, end: e, titulo: j.summary || '', diaCompleto: false });
  }
  return out;
}

function estaLibre(fecha, hora, ocupados) {
  const ini = DateTime.fromFormat(`${fecha} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
  const fin = ini.plus({ hours: 1 });
  return !ocupados.some(o => ini < o.end && fin > o.start);
}

// Huecos validos de un dia (respeta horario, festivos y ocupacion)
function huecosDelDia(fecha, asesora, prefijo, ocupados, ahora) {
  if (esFestivo(fecha, prefijo)) return [];
  const bloques = bloquesDelDia(fecha, asesora);
  if (!bloques || !bloques.length) return [];
  const huecos = [];
  for (const [a, b] of bloques) {
    let cursor = DateTime.fromFormat(`${fecha} ${a}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    const finBloque = DateTime.fromFormat(`${fecha} ${b}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
    while (cursor.plus({ hours: 1 }) <= finBloque) {
      if (cursor >= ahora && estaLibre(fecha, cursor.toFormat('HH:mm'), ocupados)) {
        huecos.push(cursor.toFormat('HH:mm'));
      }
      cursor = cursor.plus({ minutes: 30 });
    }
  }
  return huecos;
}

const DIAS = ['', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado', 'domingo'];
const MESES = ['', 'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
function nombreDia(fecha) {
  const d = DateTime.fromFormat(fecha, 'yyyy-MM-dd', { zone: ZONA });
  if (!d.isValid) return fecha;
  return `${DIAS[d.weekday]} ${d.day} de ${MESES[d.month]}`;
}
// ======================= FIN LIBRERIA COMUN ================================


// BuscarPorDireccion · EmparejarDireccion
// El feed XML de Janela NO trae la calle: solo municipio, zona, CP y coordenadas,
// y la web de Casagencia tampoco la publica. Por eso hay una pestana "Direcciones"
// en la hoja de calculo, que la agencia rellena a mano y que XMLCacheo nunca pisa.
// Por eso se extraen los TOPONIMOS del texto de cada inmueble: los nombres que
// van detras de una palabra de via ("calle X", "plaza Y", "urbanizacion Z").
// Comparar contra toponimos, y no contra el texto entero, evita que "Roma"
// case dentro de "aroma" o que "playa" convierta media cartera en candidata.
// Si algun dia se anade una columna "direccion" a la hoja, se usa automaticamente
// y con el peso mas alto, sin tocar este codigo.
// Retell manda los datos de la herramienta dentro de "args" ({ call, name, args });
// las pruebas y el WhatsApp, sueltos. Se aceptan las dos formas.
const peticion = ($('Start').first().json) ?? {};
const body = (peticion.args && typeof peticion.args === 'object') ? peticion.args : peticion;
const consulta = String(body.direccion ?? '').trim();
const municipioPedido = String(body.municipio ?? '').trim();
const operacionPedida = String(body.operacion ?? '').trim().toLowerCase();

const norm = (s) => String(s ?? '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Palabras de via: introducen un nombre de calle, no forman parte de el.
const VIA = 'calle|carrer|avenida|avinguda|avda|av|plaza|placa|pza|plza|paseo|passeig|' +
            'ronda|camino|cami|travesia|urbanizacion|urb|partida|grupo|poligono|barrio|sector';
// Palabras que cortan el nombre de la via.
const CORTE = new Set([
  'y', 'o', 'a', 'en', 'con', 'de', 'del', 'la', 'el', 'los', 'las', 'que', 'es',
  'esta', 'este', 'se', 'su', 'sus', 'por', 'para', 'un', 'una', 'al', 'desde',
  'hasta', 'muy', 'mas', 'minutos', 'metros', 'km', 'esquina', 'junto', 'cerca',
  'situado', 'situada', 'ubicado', 'ubicada', 'donde', 'tiene', 'cuenta', 'dispone'
]);
// Palabras que no distinguen un inmueble de otro dentro de la consulta.
const RUIDO = new Set([
  'calle', 'c', 'carrer', 'avenida', 'avda', 'av', 'avinguda', 'plaza', 'placa',
  'pza', 'plza', 'paseo', 'passeig', 'ronda', 'camino', 'cami', 'travesia',
  'urbanizacion', 'urb', 'partida', 'grupo', 'poligono', 'barrio', 'sector',
  'numero', 'num', 'n', 'piso', 'puerta', 'pta', 'escalera', 'esc', 'bajo', 'sn',
  'de', 'del', 'la', 'el', 'los', 'las', 'en', 'y', 'con', 'a', 'al', 'es', 'esta',
  'un', 'una', 'mi', 'su', 'por', 'llamo', 'vi', 'uno', 'busco', 'quiero', 'era',
  'inmueble', 'vivienda', 'casa', 'chalet', 'apartamento', 'local', 'sobre'
]);

// Extrae los nombres de via de un texto ya normalizado.
const reVia = new RegExp('\\b(?:' + VIA + ')\\s+(?:de\\s+(?:la\\s+|los\\s+|las\\s+)?|del\\s+)?' +
                         '([a-z0-9]+(?:\\s+[a-z0-9]+){0,2})', 'g');
function toponimos(texto) {
  const out = [];
  let m;
  reVia.lastIndex = 0;
  while ((m = reVia.exec(texto)) !== null) {
    const palabras = [];
    for (const w of m[1].split(' ')) {
      // La palabra de corte solo corta a partir de la segunda: hay vias que
      // empiezan por una ("calle En Medio", "urbanizacion La Coma").
      if ((palabras.length && CORTE.has(w)) || /^\d{3,}$/.test(w)) break;
      palabras.push(w);
    }
    // se descarta el numero de portal final: "alloza 12" -> "alloza"
    while (palabras.length > 1 && /^\d+$/.test(palabras[palabras.length - 1])) palabras.pop();
    if (palabras.length && !(palabras.length === 1 && palabras[0].length < 3)) {
      out.push(palabras.join(' '));
    }
  }
  return out;
}

let tokens = norm(consulta).split(' ').filter(t => t && !RUIDO.has(t));
let palabras = tokens.filter(t => /[a-z]/.test(t) && t.length >= 3);

// Hay calles que se llaman como una via ("Carrer Paseo", "Avenida Gran Via"):
// si al quitar las palabras de via no queda nada, se conservan. Pero solo si
// quedan DOS o mas: un "calle" suelto no es una direccion.
if (!palabras.length) {
  const todas = norm(consulta).split(' ').filter(Boolean);
  const rescate = todas.filter(t => /[a-z]/.test(t) && t.length >= 3 && !CORTE.has(t));
  if (rescate.length >= 2) { tokens = todas; palabras = rescate; }
}
const numeros = tokens.filter(t => /^\d+$/.test(t));

if (!palabras.length) {
  return [{ json: { respuesta: {
    encontrado: false, motivo: 'consulta_vacia',
    mensaje_para_sara: 'No he entendido la direccion. Pidele al cliente que repita el nombre de la calle.'
  } } }];
}

const filas = $('LeerInmuebles').all().map(i => i.json).filter(r => r && r.ref);

// Si la hoja no ha respondido, NO es que el inmueble no exista: es una
// incidencia. Decirle al cliente "no lo tengo" cuando en realidad fallo la
// lectura es peor que reconocer el problema.
if (!filas.length) {
  return [{ json: { respuesta: {
    encontrado: false, motivo: 'error_datos',
    mensaje_para_sara: 'No he podido consultar la cartera por un problema tecnico. NO le digas al cliente que ese inmueble no existe. Discupate, pidele la referencia del anuncio si la tiene, y si no, registra un mensaje para que la asesora le llame.'
  } } }];
}

// Direcciones introducidas a mano por la agencia (pestana "Direcciones").
// Si la pestana no existe o esta vacia, la busqueda sigue funcionando igual.
const manual = {};
try {
  for (const it of $('LeerDirecciones').all()) {
    const j = (it && it.json) ? it.json : {};
    if (j.ref && j.direccion) manual[String(j.ref).trim().toUpperCase()] = String(j.direccion);
  }
} catch (e) { /* sin pestana de direcciones */ }

const casaPalabra = (aguja, pajar) => new RegExp('\\b' + aguja + '[a-z]{0,3}\\b').test(pajar);

const puntuar = (r) => {
  // La direccion manual se compara entera Y por toponimos: asi vale tanto
  // "Calle Mestre Falla 39" como "Mestre Falla 39" sin palabra de via.
  const dir = norm(manual[String(r.ref).trim().toUpperCase()] || r.direccion || '');
  // Campos que de verdad indican DONDE esta el inmueble.
  const campos = [
    [dir ? [dir, ...toponimos(dir)] : [], 8],  // direccion puesta a mano: manda
    [[norm(r.zona)], 4],                       // zona del CRM: "Voramar", "Marina d'Or"
    [toponimos(norm(r.descripcion)), 3]        // "en la plaza Fadrell", "calle Alloza"
  ];
  let total = 0;
  const casan = [];
  for (const p of palabras) {
    let mejor = 0;
    for (const [lista, peso] of campos) {
      if (lista.some(t => t && casaPalabra(p, t))) { mejor = Math.max(mejor, peso); }
    }
    if (mejor) { total += mejor; casan.push(p); }
  }
  if (casan.length) {
    const todo = campos.flatMap(([lista]) => lista).join(' ');
    for (const n of numeros) {
      if (new RegExp('\\b' + n + '\\b').test(todo)) { total += 2; break; }
    }
  }
  return { total, casan: [...new Set(casan)] };
};

let candidatos = filas.map(r => ({ r, ...puntuar(r) }));

// El numero de portal que dice el cliente, si lo hay
const portalPedido = numeros.length ? Number(numeros[numeros.length - 1]) : null;
for (const c of candidatos) {
  if (!c.casan.length || portalPedido === null) continue;
  const m = norm(manual[String(c.r.ref).trim().toUpperCase()] || c.r.direccion || '').match(/\b(\d{1,4})\b/);
  // Portal cercano (52 cuando dice 56): la misma zona de la calle, un punto mas
  if (m && Number(m[1]) !== portalPedido && Math.abs(Number(m[1]) - portalPedido) <= 10) c.total += 1;
}

if (municipioPedido) {
  const m = norm(municipioPedido);
  const enMunicipio = (c) => {
    const mun = norm(c.r.municipio);
    return m.split(' ').some(w => w.length > 3 && mun.includes(w));
  };
  // Hay calles que cruzan dos municipios (la avenida Ferrandis Salvador va de
  // El Grao de Castellon a Benicassim): si la DIRECCION del inmueble casa
  // (peso 8, la puesta a mano), no se descarta por el municipio. Los del
  // municipio pedido van primero.
  const conMun = candidatos.filter(c => enMunicipio(c) || (c.casan.length && c.total >= 8));
  for (const c of conMun) if (enMunicipio(c) && c.casan.length) c.total += 1;
  if (conMun.length) candidatos = conMun;
}
if (operacionPedida) {
  const conOp = candidatos.filter(c => norm(c.r.tipo_transaccion).includes(norm(operacionPedida)));
  if (conOp.length) candidatos = conOp;
}

const MIN = 3;
candidatos = candidatos.filter(c => c.casan.length > 0 && c.total >= MIN)
  .sort((a, b) => b.total - a.total);

// Consulta demasiado vaga ("el centro", "cerca de la playa"): encaja media
// cartera y ninguno destaca. Pero si UNO gana con claridad, no es vaga: es una
// direccion buena que ademas comparte palabras con otras muchas.
// Basta con que el mejor puntue alto: eso significa que hay una direccion de
// verdad detras. Que empaten dos no es vaguedad, es que hay dos inmuebles en
// la misma calle, y ahi lo correcto es ensenar los dos y preguntar.
const hayGanador = candidatos.length > 0 && candidatos[0].total >= 8;

if (candidatos.length > 6 && !hayGanador) {
  return [{ json: { respuesta: {
    encontrado: false, motivo: 'demasiado_generico',
    mensaje_para_sara: 'Con esa direccion me encajan demasiados inmuebles. Pidele la calle exacta con el numero. Si todavia no le has preguntado por la referencia del anuncio, pidesela tambien; si ya te ha dicho que no la tiene, no insistas. NO le leas un listado.'
  } } }];
}

candidatos = candidatos.slice(0, 3);

if (!candidatos.length) {
  return [{ json: { respuesta: {
    encontrado: false, motivo: 'sin_coincidencias',
    mensaje_para_sara: 'No localizo ningun inmueble por esa direccion. Dile al cliente que por la calle no te aparece. Si todavia no le has preguntado por la referencia del anuncio, pidesela ahora; si ya te ha dicho que no la tiene, NO se la vuelvas a pedir: ofrecele buscar por municipio y caracteristicas, o registrar un mensaje para que la asesora localice el inmueble y le llame. NO le leas un listado de inmuebles que no ha pedido.'
  } } }];
}

const fmt = (c) => {
  const r = c.r;
  const precio = r.precio ? `${Number(r.precio).toLocaleString('es-ES')} euros` : 'precio a consultar';
  const dir = manual[String(r.ref).trim().toUpperCase()] || r.direccion || '';
  return `${r.tipo_inmueble || 'Inmueble'} en ${dir || r.zona || r.municipio}, referencia ${r.ref}, ` +
         `${r.habitaciones || '?'} habitaciones, ${precio} (${r.tipo_transaccion})`;
};

// Fiable cuando solo encaja uno, o cuando el primero le saca mucha ventaja al
// segundo (ej. 18 contra 3): en ese caso Sara puede confirmarlo directamente.
const fiable = candidatos[0].total >= 6 &&
  (candidatos.length === 1 || candidatos[0].total >= candidatos[1].total * 2);

return [{ json: { respuesta: {
  encontrado: true,
  fiabilidad: fiable ? 'alta' : 'media',
  coincidencias: candidatos.map(c => ({
    ref: c.r.ref, municipio: c.r.municipio, zona: c.r.zona,
    direccion: manual[String(c.r.ref).trim().toUpperCase()] || c.r.direccion || '',
    tipo: c.r.tipo_inmueble, precio: c.r.precio,
    operacion: c.r.tipo_transaccion, habitaciones: c.r.habitaciones,
    puntuacion: c.total
  })),
  mensaje_para_sara: fiable
    ? `Creo que es este: ${fmt(candidatos[0])}. Confirmaselo al cliente antes de seguir.`
